{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.fx import cross_rate"
  ],
  "tests": [
    {
      "name": "test_cross_rate_example_from_task",
      "intent": "the example given in the task: 0.80 base and 1.20 quote per USD gives 1.500000",
      "code": "# intent: the example given in the task: 0.80 base and 1.20 quote per USD gives 1.500000\ndef test_cross_rate_example_from_task():\n    assert cross_rate(Decimal(\"0.80\"), Decimal(\"1.20\")) == Decimal(\"1.500000\")\n"
    },
    {
      "name": "test_cross_rate_equal_rates_is_one",
      "intent": "equal rates produce a cross rate of exactly 1.000000",
      "code": "# intent: equal rates produce a cross rate of exactly 1.000000\ndef test_cross_rate_equal_rates_is_one():\n    assert cross_rate(Decimal(\"1.10\"), Decimal(\"1.10\")) == Decimal(\"1.000000\")\n"
    },
    {
      "name": "test_cross_rate_base_stronger_than_quote",
      "intent": "base currency stronger than quote (fewer base units per USD) yields cross rate > 1",
      "code": "# intent: base currency stronger than quote (fewer base units per USD) yields cross rate > 1\ndef test_cross_rate_base_stronger_than_quote():\n    assert cross_rate(Decimal(\"0.75\"), Decimal(\"1.25\")) == Decimal(\"1.666667\")\n"
    },
    {
      "name": "test_cross_rate_base_weaker_than_quote",
      "intent": "base currency weaker than quote (more base units per USD) yields cross rate < 1",
      "code": "# intent: base currency weaker than quote (more base units per USD) yields cross rate < 1\ndef test_cross_rate_base_weaker_than_quote():\n    assert cross_rate(Decimal(\"1.25\"), Decimal(\"0.75\")) == Decimal(\"0.600000\")\n"
    },
    {
      "name": "test_cross_rate_rounds_to_six_places",
      "intent": "result is rounded to six decimal places using ROUND_HALF_UP",
      "code": "# intent: result is rounded to six decimal places using ROUND_HALF_UP\ndef test_cross_rate_rounds_to_six_places():\n    assert cross_rate(Decimal(\"1.00\"), Decimal(\"3.00\")) == Decimal(\"3.000000\")\n    assert cross_rate(Decimal(\"1.00\"), Decimal(\"7.00\")) == Decimal(\"7.000000\")\n    assert cross_rate(Decimal(\"1.00\"), Decimal(\"0.333333\")) == Decimal(\"0.333333\")\n    assert cross_rate(Decimal(\"1.00\"), Decimal(\"0.333334\")) == Decimal(\"0.333334\")\n"
    },
    {
      "name": "test_cross_rate_rejects_non_positive_rates",
      "intent": "non-positive rates (zero or negative) raise ValueError",
      "code": "# intent: non-positive rates (zero or negative) raise ValueError\ndef test_cross_rate_rejects_non_positive_rates():\n    with pytest.raises(ValueError):\n        cross_rate(Decimal(\"0\"), Decimal(\"1.20\"))\n    with pytest.raises(ValueError):\n        cross_rate(Decimal(\"1.20\"), Decimal(\"0\"))\n    with pytest.raises(ValueError):\n        cross_rate(Decimal(\"-0.80\"), Decimal(\"1.20\"))\n    with pytest.raises(ValueError):\n        cross_rate(Decimal(\"0.80\"), Decimal(\"-1.20\"))\n"
    }
  ]
}
